빛의 방향에 따라서 망점의 크기에 변화를 주는 하프톤 패턴
Cycles의 OSL 스크립트는 엔진의 하드웨어/레이트레이싱 구조상 씬 내부 Light 오브젝트의 좌표나 방향을 직접 쿼리하는 API를 제공하지 않습니다.
따라서 수동 입력 없이 조명의 방향과 세기에 완전히 자동 반응하게 만들려면, Blender Shader Editor의 노드 데이터(Texture Coordinate - Normal)를 활용하여 방향 벡터를 스크립트로 넘겨주는 방식을 사용해야 합니다.
1. OSL 스크립트 (halftone_newsprint.osl)
// Blender 5.2 OSL - Screen-Space Halftone (Auto-Normal Responsive)
float newsprint_fract(float x) {
float f = fmod(x, 1.0);
return (f < 0.0) ? (f + 1.0) : f;
}
vector newsprint_fract_vec(vector v) {
return vector(
newsprint_fract(v[0]),
newsprint_fract(v[1]),
newsprint_fract(v[2])
);
}
float newsprint_hash(vector p) {
vector k = vector(12.9898, 78.233, 45.164);
return newsprint_fract(sin(dot(p, k)) * 43758.5453);
}
shader halftone_newsprint(
// Inputs
vector NormalInput = vector(0.0, 0.0, 1.0) [[ string label = "Normal vector" ]],
vector LightVector = vector(0.5, 0.7, 1.0) [[ string label = "Light Direction Vector" ]],
float GridScale = 80.0 [[ string label = "Screen Grid Scale", float min = 1.0, float max = 500.0 ]],
float JitterAmount = 0.08 [[ string label = "Noise Jitter", float min = 0.0, float max = 0.5 ]],
float InkDefect = 0.15 [[ string label = "Ink Defect", float min = 0.0, float max = 1.0 ]],
color BasePaperColor = color(0.82, 0.80, 0.76) [[ string label = "Paper Color" ]],
color DotBlackColor = color(0.05, 0.05, 0.05) [[ string label = "Dot Color" ]],
// Outputs
output closure color BSDF = 0,
output float DotMask = 0.0
)
{
// 1. 스크린 스페이스 좌표계 연산
vector camP = transform("camera", P);
vector screenUV = (vector(camP[0], camP[1], 0.0) + vector(1000.0, 1000.0, 0.0)) * GridScale;
// 2. 표면 법선과 입력된 조명 방향의 내적(NdotL) 자동 계산
vector N_norm = normalize(NormalInput);
vector L_norm = normalize(LightVector);
// 명암 농도 연산 (0.0 = 어두움, 1.0 = 밝음)
float NdotL = clamp(dot(N_norm, L_norm), 0.0, 1.0);
// 밝은 곳은 작은 망점(0.02), 어두운 곳은 큰 망점(0.48)
float targetRadius = mix(0.48, 0.02, NdotL);
// 3. 노이즈 및 Jitter 연산
vector cellId = floor(screenUV);
vector jitter = vector(
(newsprint_hash(cellId + vector(1.0, 0.0, 0.0)) - 0.5) * JitterAmount,
(newsprint_hash(cellId + vector(0.0, 1.0, 0.0)) - 0.5) * JitterAmount,
0.0
);
vector uv = newsprint_fract_vec(screenUV + jitter) - vector(0.5, 0.5, 0.0);
float dist = length(uv);
// 4. 질감 및 망점 알파 연산
vector worldP = transform("world", P);
float microNoise = newsprint_hash(worldP * 120.0);
float effectiveRadius = targetRadius + (microNoise - 0.5) * InkDefect * 0.15;
float dotAlpha = 1.0 - smoothstep(effectiveRadius - 0.03, effectiveRadius + 0.03, dist);
float inkFading = mix(1.0, microNoise, InkDefect * 0.4);
dotAlpha *= inkFading;
// 5. 최종 합성 및 BSDF 연산
DotMask = clamp(dotAlpha, 0.0, 1.0);
color finalColor = mix(BasePaperColor, DotBlackColor, DotMask);
BSDF = finalColor * diffuse(N_norm);
}
